SELECT order_id, status, TRIM(status) AS clean_status
FROM payments
WHERE method <> 'paypal';

SELECT payments.id, payments.amount, payments.paid_at
FROM payments
WHERE payments.order_id IS NULL AND payments.order_id IN (SELECT id FROM orders WHERE store_id IS NOT NULL);

SELECT p.id, p.order_id, p.amount
FROM payments p
WHERE p.method IN ('bank_transfer', 'promptpay', 'card') AND p.order_id IN (SELECT id FROM orders WHERE status = 'COMPLETED');

select p.id, p.price, p.product_name
from products p
where p.launch_date < '2025-10-01' and p.id in (select product_id from store_sales where product_id in (2, 5, 7, 9));

SELECT id, merchant, SUBSTRING(txn_type, 1, 4) AS txn_type_prefix
FROM transactions
WHERE amount >= 2800;

SELECT dept_id, email, CONCAT(full_name, ' - ', email) AS full_name_email
FROM employees
WHERE job_title = 'Manager';

SELECT status, amount, GREATEST(discount, shipping_fee) AS greatest_discount_shipping_fee
FROM orders
ORDER BY amount DESC;

SELECT * FROM (SELECT country, city, rating FROM suppliers WHERE supplier_name LIKE '%Pac%')
PIVOT (MAX(rating) FOR city IN ('Singapore', 'Chiang Mai', 'New York'))
ORDER BY country;

SELECT COUNT(monthly_fee) AS monthly_fee_count, ROUND(AVG(monthly_fee), 2) AS avg_monthly_fee, MAX(start_date) AS latest_start_date
FROM subscriptions
WHERE monthly_fee <= 170 AND start_date BETWEEN '2023-09-01' AND '2023-09-18';
